```markdown
<!-- openspec.md update -->
# Living System Specification

## User Management Service
- Handles user profiles, authentication tokens, and notification preferences.
- **Protocol**: gRPC (gRPC)
- **Proto Definition**: `./labs/language/cc/proto/user_service.proto`
- **Methods**:
  - `GetUser(GetUserRequest) returns (User)`
  - `UpdateSettings(UpdateSettingsRequest) returns (Settings)`
- **Legacy Support**: REST endpoints `GET /api/v1/user` and `POST /api/v1/user/settings` are now proxies to the gRPC service.
```

```java
// Refactored UserController (Simplified Example)
@RestController
@RequestMapping("/api/v1/user")
public class UserController {

    private final UserServiceBlockingStub userServiceStub;

    public UserController(UserServiceBlockingStub stub) {
        this.userServiceStub = stub;
    }

    @GetMapping
    public UserResponse getUser(@RequestParam String userId) {
        GetUserRequest request = GetUserRequest.newBuilder().setUserId(userId).build();
        User user = userServiceStub.getUser(request);
        return UserResponse.fromProto(user);
    }

    @PostMapping("/settings")
    public SettingsResponse updateSettings(@RequestBody SettingsRequest settings) {
        UpdateSettingsRequest request = UpdateSettingsRequest.newBuilder()
            .setUserId(settings.getUserId())
            .setPreferences(settings.toProto())
            .build();
        Settings updated = userServiceStub.updateSettings(request);
        return SettingsResponse.fromProto(updated);
    }
}
```

